package reconcile

import (
	"sort"
	"testing"
)

// TestGoldenReplay runs every case through the port and compares it with the output the FROZEN legacy script
// produced (testdata/golden/cases.json, regenerated by TestDifferential). It carries no build tag, so gremlins'
// -tags nodiff builds still kill mutants without bash.
func TestGoldenReplay(t *testing.T) {
	golden := readGoldens(t)
	cases := allCases()
	names := make([]string, 0, len(cases))
	for _, c := range cases {
		names = append(names, c.name)
		want, ok := golden[c.name]
		if !ok {
			t.Errorf("%s: no golden (regenerate with RECONCILE_UPDATE=1 go test -run TestDifferential)", c.name)
			continue
		}
		// Every box (and so every stub gh script) is written HERE, before any subtest runs: a parallel subtest
		// that forked while another still held a stub open for writing made exec fail with ETXTBSY, which the
		// probe reads as "gh is not authenticated" (a different case failed on each run).
		b := mkBox(t, c)
		t.Run(c.name, func(t *testing.T) {
			t.Parallel()
			if d := diffResult(want, runGo(t, b)); d != "" {
				t.Errorf("Go differs from the recorded legacy output:\n%s", d)
			}
		})
	}
	sort.Strings(names)
	if len(golden) != len(names) {
		t.Errorf("%d goldens for %d cases: remove the stale ones by regenerating", len(golden), len(names))
	}
}

func TestCaseNamesAreUnique(t *testing.T) {
	seen := map[string]bool{}
	for _, c := range allCases() {
		if seen[c.name] {
			t.Errorf("duplicate case name %q", c.name)
		}
		seen[c.name] = true
	}
}
